const body = $('Webhook').first().json.body || {};
const pantryData = $input.first().json;
const pantry = pantryData.pantry || [];
const family_size = body.family_size || 4;
const days = body.days || 7;
const dietary = body.dietary || 'none';

// Categorize pantry items
const proteins = pantry.filter(i => ['chicken', 'beef', 'pork', 'fish', 'salmon', 'shrimp', 'tofu', 'eggs', 'beans'].some(p => i.name?.toLowerCase().includes(p)));
const grains = pantry.filter(i => ['rice', 'pasta', 'bread', 'flour', 'oats', 'tortilla', 'quinoa'].some(g => i.name?.toLowerCase().includes(g)));
const produce = pantry.filter(i => ['tomato', 'onion', 'pepper', 'lettuce', 'carrot', 'potato', 'garlic', 'avocado', 'lime', 'cilantro'].some(p => i.name?.toLowerCase().includes(p)));

// Generate meal suggestions based on available ingredients
const mealTemplates = [
  { name: 'Chicken Stir Fry', needs: ['chicken', 'rice'], category: 'dinner', time: 30 },
  { name: 'Pasta Bolognese', needs: ['beef', 'pasta'], category: 'dinner', time: 45 },
  { name: 'Fish Tacos', needs: ['fish', 'tortilla'], category: 'dinner', time: 25 },
  { name: 'Scrambled Eggs & Toast', needs: ['eggs', 'bread'], category: 'breakfast', time: 10 },
  { name: 'Bean & Rice Bowl', needs: ['beans', 'rice'], category: 'lunch', time: 20 },
  { name: 'Grilled Chicken Salad', needs: ['chicken', 'lettuce'], category: 'lunch', time: 20 },
  { name: 'Shrimp Fried Rice', needs: ['shrimp', 'rice'], category: 'dinner', time: 25 },
  { name: 'Breakfast Tacos', needs: ['eggs', 'tortilla'], category: 'breakfast', time: 15 },
  { name: 'Chicken Soup', needs: ['chicken', 'carrot'], category: 'dinner', time: 40 },
  { name: 'Oatmeal with Fruit', needs: ['oats'], category: 'breakfast', time: 10 },
  { name: 'Avocado Toast', needs: ['avocado', 'bread'], category: 'breakfast', time: 5 },
  { name: 'Ground Beef Tacos', needs: ['beef', 'tortilla'], category: 'dinner', time: 25 },
  { name: 'Quinoa Salad', needs: ['quinoa', 'tomato'], category: 'lunch', time: 30 },
  { name: 'Baked Salmon', needs: ['salmon'], category: 'dinner', time: 35 }
];

const pantryNames = pantry.map(i => i.name?.toLowerCase() || '');
const possible = mealTemplates.filter(m => 
  m.needs.every(need => pantryNames.some(p => p.includes(need)))
);

// Build weekly plan
const weekPlan = [];
const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
for (let d = 0; d < days; d++) {
  const dayMeals = {
    day: dayNames[d % 7],
    breakfast: possible.filter(m => m.category === 'breakfast')[d % Math.max(1, possible.filter(m => m.category === 'breakfast').length)]?.name || 'Cereal & Milk',
    lunch: possible.filter(m => m.category === 'lunch')[d % Math.max(1, possible.filter(m => m.category === 'lunch').length)]?.name || 'Sandwich',
    dinner: possible.filter(m => m.category === 'dinner')[d % Math.max(1, possible.filter(m => m.category === 'dinner').length)]?.name || 'Leftovers'
  };
  weekPlan.push(dayMeals);
}

// Generate shopping needs
const allNeeded = new Set();
possible.forEach(m => m.needs.forEach(n => allNeeded.add(n)));
const lowStock = pantry.filter(i => (i.quantity || 1) <= 1).map(i => i.name);

return {
  json: {
    family_size: family_size,
    days_planned: days,
    dietary: dietary,
    pantry_items: pantry.length,
    available_meals: possible.length,
    meal_plan: weekPlan,
    low_stock_items: lowStock,
    suggested_recipes: possible.slice(0, 10).map(m => ({
      name: m.name,
      category: m.category,
      prep_time: m.time + ' min',
      ingredients_available: m.needs
    }))
  }
};
